window.ScripturaLexicons.BDAG_PART_0293 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-01\" data-source=\"BDAG\" data-search=\"πολυλογία, ας, ἡ substantivo feminino verbosidade, prolixidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυλογία, ας, ἡ</td><td>substantivo feminino</td><td>verbosidade, prolixidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-02\" data-source=\"BDAG\" data-search=\"πολυμερῶς advérbio em diversas partes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυμερῶς</td><td>advérbio</td><td>em diversas partes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-03\" data-source=\"BDAG\" data-search=\"πολυπλάσιος, α, ον adjetivo multiforme, múltiplo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυπλάσιος, α, ον</td><td>adjetivo</td><td>multiforme, múltiplo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-04\" data-source=\"BDAG\" data-search=\"πολυπλήθεια, ας, ἡ substantivo feminino grande multidão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυπλήθεια, ας, ἡ</td><td>substantivo feminino</td><td>grande multidão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-05\" data-source=\"BDAG\" data-search=\"πολυπλοκία, ας, ἡ substantivo feminino astúcia, ardil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυπλοκία, ας, ἡ</td><td>substantivo feminino</td><td>astúcia, ardil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-06\" data-source=\"BDAG\" data-search=\"πολυπλούσιος remissão ver πολυπλάσιος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυπλούσιος</td><td>remissão</td><td>ver πολυπλάσιος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-07\" data-source=\"BDAG\" data-search=\"πολυποίκιλος, ον adjetivo multiforme, muito variado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυποίκιλος, ον</td><td>adjetivo</td><td>multiforme, muito variado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-08\" data-source=\"BDAG\" data-search=\"πολύπους, ποδος, ὁ substantivo masculino polvo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολύπους, ποδος, ὁ</td><td>substantivo masculino</td><td>polvo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-09\" data-source=\"BDAG\" data-search=\"πολυπραγμοσύνη, ης, ἡ substantivo feminino curiosidade excessiva, minuciosidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυπραγμοσύνη, ης, ἡ</td><td>substantivo feminino</td><td>curiosidade excessiva, minuciosidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-10\" data-source=\"BDAG\" data-search=\"πολυπράγμων, ον, adjetivo inquisitivo, curioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυπράγμων, ον,</td><td>adjetivo</td><td>inquisitivo, curioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-11\" data-source=\"BDAG\" data-search=\"πολύς, πολλή, πολύ, adjetivo muito, numeroso, grande; mais; a maioria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολύς, πολλή, πολύ,</td><td>adjetivo</td><td>muito, numeroso, grande; mais; a maioria</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-12\" data-source=\"BDAG\" data-search=\"πολυσπλαγχνία, ας, ἡ substantivo feminino compaixão, misericórdia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυσπλαγχνία, ας, ἡ</td><td>substantivo feminino</td><td>compaixão, misericórdia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-13\" data-source=\"BDAG\" data-search=\"πολύσπλαγχνος, ον adjetivo compassivo, misericordioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολύσπλαγχνος, ον</td><td>adjetivo</td><td>compassivo, misericordioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-14\" data-source=\"BDAG\" data-search=\"πολυτέλεια, ας, ἡ substantivo feminino extravagância, luxo, riqueza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυτέλεια, ας, ἡ</td><td>substantivo feminino</td><td>extravagância, luxo, riqueza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-15\" data-source=\"BDAG\" data-search=\"πολυτελής, ές adjetivo caro, dispendioso, precioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυτελής, ές</td><td>adjetivo</td><td>caro, dispendioso, precioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-16\" data-source=\"BDAG\" data-search=\"πολυτελῶς advérbio abundantemente, prodigamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυτελῶς</td><td>advérbio</td><td>abundantemente, prodigamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-17\" data-source=\"BDAG\" data-search=\"πολύτιμος, ον adjetivo muito precioso, valioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολύτιμος, ον</td><td>adjetivo</td><td>muito precioso, valioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-18\" data-source=\"BDAG\" data-search=\"πολυτρόπως advérbio de muitas maneiras BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πολυτρόπως</td><td>advérbio</td><td>de muitas maneiras</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-19\" data-source=\"BDAG\" data-search=\"πόμα, ατος, τό substantivo neutro bebida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πόμα, ατος, τό</td><td>substantivo neutro</td><td>bebida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0293-20\" data-source=\"BDAG\" data-search=\"πονέω verbo labutar, trabalhar arduamente, sofrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πονέω</td><td>verbo</td><td>labutar, trabalhar arduamente, sofrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0293-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυλογία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυλογία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (X., Cyr. 1, 4, 3; Pla., Leg. 1, 641e; Plut., Mor. 6c; 519c; Vett. Val. 108, 8; 23; Herm. Wr. 14, 5; Sextus 155; Pr 10:19), discurso de extensão enfadonha, muito falar, verbosidade, prolixidade <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">π</span>. <span class=\"greek\">αὐτῶν</span> com suas muitas palavras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:2</a> D (Ael. Aristid. 45, 8 K.=8 p. 85 D.: <span class=\"greek\">θεοὺς</span> <span class=\"greek\">ἄνευ</span> <span class=\"greek\">μέτρων</span> <span class=\"greek\">προσαγορεύοντες</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">αἰσχυνόμεθα</span>=não nos envergonhamos de dirigir-nos aos deuses sem mantras/encantamentos).—DELG s.v. <span class=\"greek\">λέγω</span> B. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυμερῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυμερῶς</span> (<span class=\"greek\">μέρος</span>) adv. (Diod S 5, 37, 2; Plut., Mor. 537d; várias vezes em Vett. Val. [índice III]; Jos., Ant. 12, 54) de <span class=\"greek\">πολυμερής</span>, <span class=\"greek\">ές</span> (Aristot.; Plut., Mor. 427b; 757d; PGM 13, 304; Wsd 7:22; Ar. 13, 5 o corpo é constituído ‘de muitas partes’; Tat. 15, 1 a alma é composta; v. também Porph., Sent. 34), acerca da escrita profética, em diversas partes, com <span class=\"greek\">πολυτρόπως</span>=‘de diversas maneiras’ (as duas palavras juntas também em Maximus Tyr. 1, 2b; 11, 7a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:1</a> (sobre a aliteração, cf. o início de Philo, <span class=\"greek\">περὶ</span> <span class=\"greek\">μετανοίας</span>; para a predileção extrema pelos sons de <span class=\"greek\">π</span>, v. p. ex. Gorgias 11, 11). Muitos traduzem de muitas maneiras (L-S-J-M citam Plut., Mor. 537d em apoio, mas essa passagem refere-se aos numerosos aspectos do corpo deformado de Tersites, cujas diversas partes são descritas em Il. 2, 217–19), assim NRSV: ‘de muitas e diversas maneiras’. Se ‘muitas maneiras’ em tal tradução se refere a uma variedade de passagens das Escrituras, os tradutores têm o apoio da Vulgata: multifariam. Mas, para evitar uma impressão de banalidade, é melhor traduzir na linha sugerida acima. Além disso, a estrutura retórica de Hb requer alguma preparação no prólogo para as numerosas referências ao AT.—DELG s.v. <span class=\"greek\">μείρομαι</span> II. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυπλάσιος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυπλάσιος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (sobre a forma, v. Schwyzer I 446; 2 Macc 9:16; Philo; Agis, Anth. Pal. 6, 152; PPanop 2, 232 [III d.C.]), multiforme <span class=\"greek\">καρπὸν</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">μονοούσιον</span> <span class=\"greek\">πολυπλάσιον</span> sua colheita de retidão, única e diversa GJs 6:3 (códices; v. deStrycker 225–27. O papiro e outros códices apresentam <span class=\"greek\">πολυπλούσιον</span>, de resto desconhecido, ‘abundantemente rico’).—DELG s.v. <span class=\"greek\">πέλας</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυπλήθεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυπλήθεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πολύς</span>, <span class=\"greek\">πλῆθος</span>; Hippocr. et al.; Menand., Dysc. 166; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 32, 1 p. 56, 5 V.; Ps.-Plut., Hom. 85; Dit., Syll. 880, 40; 2 Macc 8:16), grande multidão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:7</a> v.l. (em um acréscimo no códice E; o códice D apresenta <span class=\"greek\">πλῆθος</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">π</span>. (<span class=\"greek\">πολυπληθίαν</span> deve ser rejeitado, com Lghtf., e <span class=\"greek\">πολυπλήθειαν</span>, também atestado, deve ser inserido) <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἀπείληφα</span> recebi toda a vossa (grande) congregação IEph 1:3.—DELG s.v. <span class=\"greek\">πίμπλημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυπλοκία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυπλοκία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πολύπλοκος</span> ‘emaranhado, complexo’ [<span class=\"greek\">πλέκω</span>]; Theognis 67), prática de intrigas complexas, astúcia, ardil <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span> Hm 4, 3, 4.—DELG s.v. <span class=\"greek\">πλέκω</span> B.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυπλούσιος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυπλούσιος</span> v. <span class=\"greek\">πολυπλάσιος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυποίκιλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυποίκιλος</span>, <span class=\"greek\">ον</span> (v. <span class=\"greek\">ποικίλος</span>; Eur. et al.), relativo a ser diversificado, de (muitas) facetas (assim Orph. Hymn., 6, 11; 61, 4 [<span class=\"greek\">λόγος</span>]; TestSol 4:4 e C 11:4 [<span class=\"greek\">τρόπος</span>]; SibOr 8, 120 [<span class=\"greek\">ὀργή</span>]) <span class=\"greek\">σοφία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:10</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύπους, ποδος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολύπους</span>, <span class=\"greek\">ποδος</span>, <span class=\"greek\">ὁ</span> polvo (Hom. et al.; Ps.-Phoc. 49; Philo, Ebr. 172; Tart. 2, 1), com moreia e sépia B 10:5 (a edição de vGebhardt apresenta <span class=\"greek\">πώλυπα</span> [v. <span class=\"greek\">πῶλυψ</span>]. <span class=\"greek\">πολύποδα</span> também é atestado; Bihlmeyer ad loc.; cf. Lev 11:10; v. também <span class=\"greek\">σηπία</span> e <span class=\"greek\">σμύραινα</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυπραγμοσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυπραγμοσύνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (v. artigo seguinte; Thu., Aristoph. et al., sobretudo em sentido desfavorável, como ‘curiosidade excessiva, intromissão, indiscrição’; v. especialmente Plut., Mor. 515b–23), estado de interesse excessivo por pormenores de pouca importância, minuciosidade excessiva, <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἰουδαίων</span> <span class=\"greek\">πολυπρ</span>. Dg 4:6.—AAdkins, ClPh 71, ’76, 301–27.—DELG s.v. <span class=\"greek\">πράσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυπράγμων, ον,</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυπράγμων</span>, <span class=\"greek\">ον</span>, gen. <span class=\"greek\">ονος</span> (cf. artigo anterior; desde Eupolis Com. [V a.C.] 222, Lysias, Aristoph.; Philo Bybl. [100 d.C.]: 790 Fgm. 1 [24] Jac. [em Eu., PE 1, 9, 24]; Philo Alex., Abr. 20, Spec. Leg. 1, 69; Jos., Ant. 15, 182), se no sentido favorável mais raro (Polyb. 9, 4, 4; cf. <span class=\"greek\">πολυπραγμονέω</span> ‘investigar’ New Docs 1 n. 12, 15), inquisitivo <span class=\"greek\">π</span>. <span class=\"greek\">ἄνθρωποι</span> Dg 5:3.—DELG s.v. <span class=\"greek\">πράσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύς, πολλή, πολύ,</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολύς</span>, <span class=\"greek\">πολλή</span>, <span class=\"greek\">πολύ</span>, gen. <span class=\"greek\">πολλοῦ</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">οῦ</span> (Hom.+; inscrições, papiros, LXX, pseudepígrafos, Philo, Joseph., apologistas) ‘muito’.—Comparativo <span class=\"greek\">πλείων</span>, <span class=\"greek\">πλεῖον</span> (18 vezes no NT, 4 vezes nos Padres Apostólicos [incluindo Hv 3, 6, 4; Hs 8, 1, 16] e Ath. 12, 3) ou <span class=\"greek\">πλέον</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:13</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:28</a> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">πλέον</span>; de resto, <span class=\"greek\">πλέον</span> no NT somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:15</a>; 14 vezes nos Padres Apostólicos [incl. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">πλέον</span> Hs 1, 1, 6]; Ar. duas vezes; Just. 6 vezes; Tat. uma vez; Ath. 7 vezes), <span class=\"greek\">ονος</span>; pl. <span class=\"greek\">πλείονες</span>, e ac. <span class=\"greek\">πλείονας</span> contraído <span class=\"greek\">πλείους</span>, neut. <span class=\"greek\">πλείονα</span> e <span class=\"greek\">πλείω</span> (este último <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:53</a> [<span class=\"greek\">πλεῖον</span>, <span class=\"greek\">πλείου</span> vv.ll.]; B-D-F §30, 2; Mlt-H. 82; Thackeray p. 81f; Mayser p. 68f) ‘mais’ (Hom.+; inscrições, papiros, LXX; TestAbr B 7 p. 111, 27=Stone p. 70 [<span class=\"greek\">πλείον</span>]; TestJob 35:2; TestGad 7:2 [<span class=\"greek\">πλεῖον</span>]; AscIs 3:8; [<span class=\"greek\">πλέον</span>]; EpArist; apologistas, exceto Mel.).—Superlativo <span class=\"greek\">πλεῖστος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> ‘a maioria, muitíssimo’ (Hom.+).</p><p class=\"entry-text\">① Relativo a constituir um grande número, muitos, grande número de.</p><p class=\"entry-text\">ⓐ Grau positivo <span class=\"greek\">πολύς</span>, <span class=\"greek\">πολλή</span>, <span class=\"greek\">πολύ</span></p><p class=\"entry-text\"><span class=\"greek\">α</span>. Adj., precedendo ou seguindo um substantivo (ou part. ou adj. usado como substantivo) no pl., muitos, numerosos <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">πολλαί</span> muitos feitos poderosos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:22b</a>. <span class=\"greek\">δαιμονιζόμενοι</span> <span class=\"greek\">πολλοί</span> 8:16. Cf. v. 30; 9:10; 13:17; 24:11; 27:52, 55; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:15a</a>; 6:13; 12:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>, 27; 7:21b; 10:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:32</a>; 14:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:3</a>; 2:43; 8:7b; 14:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:17f</a> (Gen 17:5); 8:29; 12:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:5ab</a>; 11:30; 12:12a, 20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:1</a>; 2J 7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:11</a>; 9:9; 10:11; 1 Cl 55:3ab. <span class=\"greek\">ἔτη</span> <span class=\"greek\">πολλά</span> muitos anos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:19b</a> (<span class=\"greek\">εἰς</span> <span class=\"greek\">ἔτη</span> <span class=\"greek\">π</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:10</a> (<span class=\"greek\">ἐκ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐτῶν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:23</a> (<span class=\"greek\">ἀπὸ</span> <span class=\"greek\">π</span>. [v.l. <span class=\"greek\">ἱκανῶν</span>] <span class=\"greek\">ἐτῶν</span>).—<span class=\"greek\">αἱ</span> <span class=\"greek\">ἁμαρτίαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">πολλαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:47a</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">εὐεργεσίαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">π</span>. 1 Cl 21:1.—<span class=\"greek\">πολλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βαρέα</span> <span class=\"greek\">αἰτιώματα</span> muitas acusações graves <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:7</a> (cf. Ps.-Pla., Sisyph. 1, 387a <span class=\"greek\">πολλά</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καλὰ</span> <span class=\"greek\">πράγματα</span>; B-D-F §442, 11; Rob. 655). <span class=\"greek\">πολλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄλλα</span> <span class=\"greek\">σημεῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:30</a> (sobre a forma X., Hell. 5, 4, 1 <span class=\"greek\">πολλὰ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄλλα</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἑλληνικὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βαρβαρικά</span>; Dionys. Hal. 2, 67, 5; Ps.-Demetr. 142 <span class=\"greek\">πολλὰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄλλας</span> <span class=\"greek\">χάριτας</span>; Jos., Ant. 3, 318; Tat. 38, 1. Sobre o assunto Bultmann 540, 3; também Porphyr., Vi. Pyth. 28 após uma narrativa de milagre: <span class=\"greek\">μυρία</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἕτερα</span> <span class=\"greek\">θαυμαστότερα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θειότερα</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τἀνδρὸς</span> … <span class=\"greek\">εἴρηται</span> <span class=\"greek\">κτλ</span>.).—<span class=\"greek\">ἄλλοι</span> <span class=\"greek\">πολλοί</span> muitos outros IRo 10:1. <span class=\"greek\">ἄλλαι</span> <span class=\"greek\">πολλαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:41</a>. <span class=\"greek\">ἄλλα</span> <span class=\"greek\">πολλά</span> (Jos., Bell. 6, 169, Ant. 9, 242; Just., D. 8, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:25</a>. <span class=\"greek\">ἕτεροι</span> <span class=\"greek\">πολλοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:35</a>. <span class=\"greek\">ἕτερα</span> <span class=\"greek\">πολλά</span> (Jos., Vi. 39) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.65\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:65</a>.—Predicativo: <span class=\"greek\">πολλοί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐισερχόμενοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:13</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:9</a>; 6:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:27</a> (Is 54:1). AcPl Ha 5, 16.—<span class=\"greek\">οὐ</span> <span class=\"greek\">πολλοί</span> não muitos=(apenas) poucos <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλαὶ</span> <span class=\"greek\">ἡμέραι</span> (Jos., Ant. 5, 328, Vi. 309) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:5</a>; AcPl Ha 11, 1. <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">σοφοί</span> não muitas (pessoas) sábias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:26a</a>; cf. bc. <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλοί</span> <span class=\"greek\">πατέρες</span> não muitos pais 4:15.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Substantivado.</p><p class=\"entry-text\">א . <span class=\"greek\">πολλοί</span> muitos, isto é, pessoas—sem art. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:22</a>; 8:11; 12:15; 20:28; 24:5ab; 26:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:2</a>; 3:10 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:15</a> apresenta <span class=\"greek\">πάντας</span> em sentido ascensivo; outras passagens a comparar neste contexto são <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:45</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:28</a> <span class=\"greek\">πολλῶν</span> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:6</a> <span class=\"greek\">πάντων</span>. Cf. a dupla tradição do dito de Bias em Clem. de Alexandria, Strom. 1, 61, 3 <span class=\"greek\">πάντες</span> <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">κακοὶ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πλεῖστοι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">κακοί</span>.—Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:45</a>, v. OCullmann, TZ 4, ’48, 471–73); 6:2; 11:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:1</a> (cf. Herm. Wr. 11, 1, 1b e v. JBauer, NovT 4, ’60, 263–66), 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:23</a>; 8:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:16</a> (<span class=\"greek\">πολλοί</span>=uma pluralidade); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:2</a>. AcPl Ha 5, 8; 7, 5; 11, 3. Oposto a <span class=\"greek\">ὀλίγοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:14</a>; 20:16 v.l. (cf. Pla., Phd. 69c <span class=\"greek\">ναρθηκοφόροι</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πολλοί</span>, <span class=\"greek\">βάκχοι</span> <span class=\"greek\">δέ</span> <span class=\"greek\">τε</span> <span class=\"greek\">παῦροι</span>=os portadores do tirso [oficiantes] são muitos, mas os verdadeiramente inspirados são poucos)—Com gen. partitivo <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Φαρισαίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:7</a>. <span class=\"greek\">π</span>. <span class=\"greek\">πῶν</span> <span class=\"greek\">υἱῶν</span> <span class=\"greek\">Ἰσραήλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:16</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:39</a>; 12:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:4</a>; 8:7a; 13:43; 18:8; 19:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:11</a>.—Com <span class=\"greek\">ἐκ</span> e gen. (AscIs 3:1; Jos., Ant. 11, 151) <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαθητῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.60\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:60</a>, 66.—10:20; 11:19, 45; 12:42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:12</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχλου</span> <span class=\"greek\">πολλοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:31</a> (Appian, Iber. 78 §337 <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλήθους</span>).</p><p class=\"entry-text\">ב . <span class=\"greek\">πολλά</span>—muitas coisas, muito, sem art.: <span class=\"greek\">γράφειν</span> escrever extensamente B 4:9. <span class=\"greek\">διδάσκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:2</a>; 6:34b. <span class=\"greek\">λαλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:3</a>. <span class=\"greek\">μηχανᾶσθαι</span> MPol 3. <span class=\"greek\">πάσχειν</span> (Pind., O. 13, 63 e outros; Jos., Ant. 13, 268; 403) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:26a</a>; 9:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:22</a>; 17:25; B 7:11; AcPl Ha 8, 19. <span class=\"greek\">ποιεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:20</a> v.l. Unido a outro neut. por <span class=\"greek\">καί</span> (Lucian, Icar. 20 <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δεινά</span>; Ael. Aristid. 46 p. 345 D.: <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">καλά</span>; Ps.-Demetr., El. 70 <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄλλα</span>; igualmente Appian, Bell. Civ. 5, 13 §53; Arrian, Anab. 6, 11, 2) <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἕτερα</span> muitas outras coisas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:18</a>. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄλλα</span> <span class=\"greek\">εἰπεῖν</span> <span class=\"greek\">ἔχοιμι</span> Dg 2:10 (Eur., Ep. 3, 2, <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἕτερα</span> <span class=\"greek\">εἰπεῖν</span> <span class=\"greek\">ἔχω</span>; Diod S 17, 38, 3 <span class=\"greek\">πολλὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄλλα</span> … <span class=\"greek\">διαλεχθείς</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλοῖς</span> de muitas maneiras (Diod S 26, 1, 2; OGI 737, 7 [II a.C.]; Just., D. 124, 4 [acerca de uma linha de argumentação]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:22a</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πολλῶν</span> (oposto a <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ὀλίγα</span>) sobre muitas coisas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:21</a>, 23.—Com art. (Pla., Apol. 1, 17a) <span class=\"greek\">τὰ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">πράσσειν</span> tratar de muitos negócios Hs 4:5b.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Em construção elíptica <span class=\"greek\">δαρήσεται</span> <span class=\"greek\">πολλά</span> (subentenda-se <span class=\"greek\">πληγάς</span>) receberá muitos (açoites) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:47</a> (B-D-F §154; 241, 6).</p><p class=\"entry-text\">ⓑ Comparativo <span class=\"greek\">πλείων</span>, <span class=\"greek\">πλεῖον</span></p><p class=\"entry-text\"><span class=\"greek\">α</span>. Adj. com um pl. (Diod S 14, 6, 1 <span class=\"greek\">μισθοφόρους</span> <span class=\"greek\">πλείους</span>=muitos mercenários) <span class=\"greek\">πλείονας</span> <span class=\"greek\">πόνους</span> (oposto a <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">δύο</span>) 1 Cl 5:4. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">πλείους</span> durante um (grande) número de dias, durante muitos dias (Jos., Ant. 4, 277; cf. Theophr. em Apollon. Paradox. 29 <span class=\"greek\">πλείονας</span> <span class=\"greek\">ἡμ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:31</a>.—21:10 (Jos., Ant. 16, 15); 24:17; 25:14; 27:20. <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πλείονές</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">γεγονότες</span> <span class=\"greek\">ἱερεῖς</span> os sacerdotes de outrora existiram em maior número <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:23</a>. <span class=\"greek\">ἑτέροις</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">πλείοσιν</span> com muitas outras palavras (além das que foram relatadas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:40</a>. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕτερα</span> <span class=\"greek\">πλείονα</span> MPol 12:1.—Com gen. de comparação (Just., A I 53, 3; Tat. 3, 2) <span class=\"greek\">ἄλλους</span> <span class=\"greek\">δούλους</span> <span class=\"greek\">πλείονας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρώτων</span> outros escravos, mais numerosos que os (que enviara) primeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:36</a>. <span class=\"greek\">πλείονα</span> <span class=\"greek\">σημεῖα</span> <span class=\"greek\">ὧν</span> mais sinais que aqueles que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:31</a>. Também com <span class=\"greek\">ἤ</span>: <span class=\"greek\">πλείονας</span> <span class=\"greek\">μαθητὰς</span> <span class=\"greek\">ἤ</span> mais discípulos que 4:1. Depois de <span class=\"greek\">πλείονες</span> (-<span class=\"greek\">α</span>), antes de numerais, omite-se a palavra correspondente a ‘que’ (B-D-F §185, 4; Kühner-G. II 311; Rob. 666; Jos., Ant. 14, 96) <span class=\"greek\">ἐτῶν</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">πλειόνων</span> <span class=\"greek\">τεσσεράκοντα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span> o homem tinha mais de 40 anos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:22</a>. <span class=\"greek\">πλείους</span> <span class=\"greek\">τεσσεράκοντα</span> 23:13, 21. Cf. 24:11; 25:6 (Jos., Ant. 6, 306 <span class=\"greek\">δέκα</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πλείους</span> <span class=\"greek\">ἡμέρας</span>).—A referência é à extensão relativa (cf. 2b<span class=\"greek\">α</span>) em <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἕσχατα</span> <span class=\"greek\">πλείονα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρώτων</span> tuas obras, das quais as últimas são maiores que as primeiras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:19</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Substantivado.</p><p class=\"entry-text\">א . (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πλείονες</span>, (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πλείους</span> a maioria, a maior parte (Diog. L. 1, 20; 22; Jos., Ant. 10, 114) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:32</a>; 27:12. Com <span class=\"greek\">ἐξ</span>: <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πλείονες</span> a maioria dos quais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:6</a>. Com gen. e uma negação (litotes) <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πλείοσιν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ηὐδόκησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> Deus se agradou de apenas poucos deles 10:5. Talvez (v. ג abaixo) este seja o lugar de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:6</a>; 9:2. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>; MPol 5:1.</p><p class=\"entry-text\">ב . (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πλείονες</span>, (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πλείους</span> (ainda) mais <span class=\"greek\">πλείονες</span> em número ainda maior <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:23</a>. <span class=\"greek\">πολλῷ</span> <span class=\"greek\">πλείους</span> <span class=\"greek\">ἐπίστευσαν</span> muitos mais vieram a crer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:41</a>.—<span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πλειόνων</span> a um número cada vez maior de pessoas=aquelas que ainda devem ser conquistadas para Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:15</a>.</p><p class=\"entry-text\">ג . (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πλείονες</span>, (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πλείους</span>. Em contraste com uma minoria, <span class=\"greek\">οἱ</span> <span class=\"greek\">πλείονες</span> pode adquirir o sentido de os outros, os restantes (assim <span class=\"greek\">τὰ</span> <span class=\"greek\">πλείονα</span> Soph., Oed. Col. 36; <span class=\"greek\">τὸ</span> <span class=\"greek\">πλέον</span> Thu. 4, 30, 4; Jos., Ant. 12, 240; B-D-F §244, 3). Assim talvez (v. א acima) <span class=\"greek\">ἵνα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πλείονας</span> <span class=\"greek\">κερδήσω</span> (em oposição ao próprio apóstolo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:6</a> (em oposição àquele que foi punido com excessiva severidade.—Nesse caso [v. א acima], sua punição teria sido determinada por voto unânime da assembleia cristã, e não por uma maioria). Cf. 9:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>; MPol 5:1.</p><p class=\"entry-text\">ד . <span class=\"greek\">πλείονα</span> (em lugar de <span class=\"greek\">πλεῖον</span>) mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:10</a> v.l.; diversas coisas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:53</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">πλείονα</span> 1 Cl 24:5 (v. como adv. ParJer 7:26).</p><p class=\"entry-text\">ⓒ Adj. superl. <span class=\"greek\">πλείστη</span> com um pl., a maior parte de <span class=\"greek\">αἱ</span> <span class=\"greek\">πλεῖσται</span> <span class=\"greek\">δυνάμεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:20</a> (diferentemente B-D-F §245, 1).</p><p class=\"entry-text\">② Relativo a ser relativamente grande em quantidade ou medida, muito, extenso.</p><p class=\"entry-text\">ⓐ Grau positivo <span class=\"greek\">πολύς</span>, <span class=\"greek\">πολλή</span>, <span class=\"greek\">πολύ</span></p><p class=\"entry-text\"><span class=\"greek\">α</span>. Adj. que precede ou segue um substantivo (ou part. ou adj. usado como substantivo)</p><p class=\"entry-text\">א . No sing., muito, grande <span class=\"greek\">πολὺς</span> <span class=\"greek\">ἀριθμός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:21</a>. Com palavras que por si mesmas denotam uma pluralidade (Appian, Bell. Civ. 5, 80 §338 <span class=\"greek\">στρατὸς</span> <span class=\"greek\">πολύς</span>) <span class=\"greek\">πολὺς</span> <span class=\"greek\">ὄχλος</span> (v. <span class=\"greek\">ὄχ</span>. 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:14</a>; 20:29; 26:47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:21</a>, 24; 6:34a; 8:1; 9:14; 12:37 (<span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ὄχ</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:29</a>; 6:17a; 8:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:2</a>, 5 (para a expressão <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄχλος</span> <span class=\"greek\">πολύς</span>, em que <span class=\"greek\">π</span>. segue o substantivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:9</a>, 12, cf. Arrian, Anab. 1, 9, 6 <span class=\"greek\">ὁ</span> <span class=\"greek\">φόνος</span> <span class=\"greek\">πολύς</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:9</a>; 19:1, 6. <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλῆθος</span> (v. pl. 2b<span class=\"greek\">α</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:7f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:6</a>; 6:17b; 23:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:1</a>; 17:4; 1 Cl 6:1. <span class=\"greek\">λαὸς</span> <span class=\"greek\">πολύς</span> muita gente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:10</a>. Acerca de dinheiro e seu valor, empregado também em linguagem figurada <span class=\"greek\">μισθὸς</span> <span class=\"greek\">πολύς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:23</a>, 35 (todos os três predicativos, como Gen 15:1). <span class=\"greek\">ἐργασία</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:16</a>. <span class=\"greek\">π</span>. <span class=\"greek\">κεφάλαιον</span> 22:28. <span class=\"greek\">χρυσοῦ</span> <span class=\"greek\">πολλοῦ</span> … <span class=\"greek\">τρυφῆς</span> <span class=\"greek\">πολλῆς</span> AcPl Ha 2, 19.—Acerca de coisas que ocorrem em massa ou em grandes quantidades (Diod S 3, 50, 1 <span class=\"greek\">πολλὴ</span> <span class=\"greek\">ἄμπελος</span>) <span class=\"greek\">γῆ</span> <span class=\"greek\">πολλή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:5</a>; <span class=\"greek\">θερισμὸς</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:2</a> (ambos pred.). <span class=\"greek\">χόρτος</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:10</a>; <span class=\"greek\">καρπὸς</span> <span class=\"greek\">π</span>. (Cyranides p. 121, 11) 12:24; 15:5, 8.—<span class=\"greek\">λόγος</span> <span class=\"greek\">π</span>. um longo discurso (Diod S 13, 1, 2; Just., D. 123, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:32</a>; 20:2. <span class=\"greek\">περὶ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">πολὺς</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> acerca disto temos muito a dizer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:11</a> (cf. Pla., Phd. 115d).—Acerca de tempo: <span class=\"greek\">πολὺς</span> <span class=\"greek\">χρόνος</span> muito tempo (Hom. et al.; Demetr.(?): 722 Fgm. 7; Jos., Ant. 8, 342; 19, 28; Just., A II, 2, 11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:6</a> (v. <span class=\"greek\">ἔχω</span> 7b); Hs 6, 4, 4 (pred.). <span class=\"greek\">μετὰ</span> <span class=\"greek\">πολὺν</span> <span class=\"greek\">χρόνον</span> (Jos., Ant. 12, 324) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:19</a>. Diferentemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:35ab</a> (v. 3a<span class=\"greek\">α</span>).</p><p class=\"entry-text\">ב . Adj. com um substantivo no pl., muitos, grandes, extensos, abundantes <span class=\"greek\">ὄχλοι</span> <span class=\"greek\">πολλοί</span> grandes multidões ou, provavelmente melhor, muita gente (como Diod S 20, 59, 2; Ps.-Clem., Hom. 10, 3. Para o sentido correspondente de <span class=\"greek\">ὄχλοι</span>, v. <span class=\"greek\">ὄχλος</span> 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:25</a>; 8:1; 13:2; 15:30a; 19:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:15</a>; 14:25. <span class=\"greek\">κτήματα</span> <span class=\"greek\">πολλά</span> muitos bens <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:22</a> (cf. Da 11:28 <span class=\"greek\">χρήματα</span> <span class=\"greek\">π</span>.). <span class=\"greek\">ὕδατα</span> <span class=\"greek\">πολλά</span> muita água, muitas águas (Maximus Tyr. 21, 3g acerca do Nilo <span class=\"greek\">ὁ</span> <span class=\"greek\">πολὺς</span> <span class=\"greek\">ποταμός</span>, igualmente Procop. Soph., Ep. 111) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:15</a>; 14:2; 17:1; 19:6b. <span class=\"greek\">θυμιάματα</span> <span class=\"greek\">πολλά</span> grande quantidade de incenso 8:3. <span class=\"greek\">τὰ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">γράμματα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:24</a>. <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">χρόνοι</span> longos períodos de tempo (Plut., Thes. 6, 9). <span class=\"greek\">πολλοῖς</span> <span class=\"greek\">χρόνοις</span> durante longos períodos de tempo (SIG 836, 6; papiros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:29</a>; 1 Cl 44:3. <span class=\"greek\">χρόνοις</span> <span class=\"greek\">πολλοῖς</span> AcPlCor 2:10. <span class=\"greek\">ἐκ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">χρόνων</span> (Diod S 3, 47, 8; Jos., Ant. 14, 110; 17, 204) 1 Cl 42:5.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Substantivado.</p><p class=\"entry-text\">א . <span class=\"greek\">πολλοί</span> muitos, isto é, pessoas—com art. <span class=\"greek\">οἱ</span> <span class=\"greek\">πολλοί</span> os muitos, conforme o que se apresenta no contexto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:2</a> v.l. (as muitas pessoas que estavam presentes na sinagoga); 9:26b (toda a multidão). Oposto a <span class=\"greek\">ὁ</span> <span class=\"greek\">εἷς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:15ac</a>, 19ab; os muitos que constituem o <span class=\"greek\">ἓν</span> <span class=\"greek\">σῶμα</span> o único corpo 12:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:17</a>. Paulo atenta para os interesses dos muitos, em vez de para os seus próprios, v. 33 (cf. Jos., Ant. 3, 212).—A maioria, a maior parte (X., An. 5, 6, 19; Appian, Maced. 7, Bell. Civ. 4, 73 §309; 2 Macc 1:36; En 104:10; AscIs 3:26; Jos., Ant. 17, 72; Just., D. 4, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a> v.l. Com conotação de desaprovação, a maioria das pessoas, a massa (Socrat., Ep. 6, 2; Dio Chrys. 15 [32], 8; Epict. 1, 3, 4; 2, 1, 22 e outros; Plut., Mor. 33a; 470b; Plotinus, Enn. 2, 9, 9; Philo, Rer. Div. Her. 42) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:17</a>; Pol 2:1; 7:2.—Jeremias, The Eucharistic Words of Jesus3, trad. NPerrin, ’66, 179–82; 226–31, e TW VI 536–45: <span class=\"greek\">πολλοί</span>.</p><p class=\"entry-text\">ב . <span class=\"greek\">πολύ</span> muito <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐδόθη</span> <span class=\"greek\">πολύ</span>, <span class=\"greek\">πολὺ</span> <span class=\"greek\">ζητηθήσεται</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">παρέθεντο</span> <span class=\"greek\">πολὺ</span> <span class=\"greek\">κτλ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:48</a> (Just., A I, 17, 4 duas vezes <span class=\"greek\">πλέον</span>). Cf. 16:10ab; 2 Cl 8:5; <span class=\"greek\">καρποφορεῖν</span> <span class=\"greek\">π</span>. dar muito fruto Hs 2:3. <span class=\"greek\">πολὺ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τρόπον</span> muito em todos os sentidos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:2</a> (Ael. Aristid. 34, 43 K.=50 p. 562 D. dá resposta a uma pergunta semelhante formulada por ele mesmo: <span class=\"greek\">πολλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παντοῖα</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:16</a>.—Como gen. de preço <span class=\"greek\">πολλοῦ</span> por uma grande soma de dinheiro (Menand., Fgm. 197 Kö.; PRyl 244, 10. V. <span class=\"greek\">στρουθίον</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:9</a>.—Acerca de tempo: <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πολύ</span> (durante) muito tempo (JosAs 19:3; Ar. 65, 3; v. também <span class=\"greek\">ἐπί</span> 18c<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:6</a>; AcPl Ha 10, 21. <span class=\"greek\">μετ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">πολύ</span> pouco depois <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:14</a> (<span class=\"greek\">μετά</span> B 2c).—<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πολύ</span> mais de uma vez, frequentemente (Is 55:7) Hm 4, 1, 8.—Antes de um comp. (como Hom. et al.; B-D-F §246; Rob. 664), no ac. <span class=\"greek\">πολὺ</span> <span class=\"greek\">βέλτιον</span> muito melhor Hs 1:9. <span class=\"greek\">π</span>. <span class=\"greek\">ἐλάττων</span> v 3, 7, 6 (Ar. 6, 2). <span class=\"greek\">π</span>. <span class=\"greek\">μᾶλλον</span> muito mais, em grau muito maior (Dio Chrys. 2, 10; 17; 64 e outros; Ael. Aristid. 34, 9 K.=50 p. 549 D.; Just., A II, 8, 3; D. 95, 1 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9</a>, 25 (mediante uma negação, adquire o sentido de muito menos; cf. Diod S 7, 14, 6 <span class=\"greek\">πολὺ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">μὴ</span> … =ainda muito menos); Dg 2:7b. <span class=\"greek\">π</span>. <span class=\"greek\">πλέον</span> 2:7a (Ar. 11, 7). <span class=\"greek\">π</span>. <span class=\"greek\">σπουδαιότερος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:22b</a>. Cf. <span class=\"greek\">π</span>. <span class=\"greek\">τιμώτερον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:7</a> v.l.; no dat. de grau de diferença <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μᾶλλον</span> (Thu. 2, 51, 4; UPZ 42, 48 [162 a.C.]; EpArist 7; 24 e outros; Sir pról. linha 14; Jos., Ant. 18, 184; Just., A I, 68, 9; Tat. 17, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:48b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:9f</a>, 15b, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:9</a>, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:12</a>. <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">κρείσσον</span> 1:23 (v.l. sem <span class=\"greek\">μᾶλλον</span>). <span class=\"greek\">πολλῷ</span> <span class=\"greek\">πλείους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:41</a>. <span class=\"greek\">πολλῷ</span> <span class=\"greek\">στρουθίων</span> como v.l. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:31</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:7</a> (ambos no aparato de N.25; acerca do forte apoio manuscrito a esta leitura, v. RBorger, TRu 52, ’87, 21–24).—Com art. <span class=\"greek\">τὸ</span> <span class=\"greek\">πολύ</span> (oposto a <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀλίγον</span>, como X., An. 7, 7, 36) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:15</a> (cf. Ex 16:18).</p><p class=\"entry-text\">ג . <span class=\"greek\">πολύς</span> (Diod S 14, 107, 4 <span class=\"greek\">πολὺς</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τιμωρίᾳ</span>=ele estava fortemente inclinado a punir) <span class=\"greek\">μὴ</span> <span class=\"greek\">πολὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥήμασιν</span> <span class=\"greek\">γίνου</span> não sejas prolixo no falar, não tagareles 1 Cl 30:5 (Job 11:3).—<span class=\"greek\">Παπίας</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πολύς</span> Papias (7), provavelmente a entender como <span class=\"greek\">ὁ</span> <span class=\"greek\">πάνυ</span>; v. <span class=\"greek\">πάνυ</span> d.</p><p class=\"entry-text\">ⓑ Comp. <span class=\"greek\">πλείων</span>, <span class=\"greek\">πλεῖον</span>; adv. <span class=\"greek\">πλειόνως</span></p><p class=\"entry-text\"><span class=\"greek\">α</span>. Adj., com um sing. (TestJob 35:2 <span class=\"greek\">διὰ</span> <span class=\"greek\">πλείονος</span> <span class=\"greek\">εὐωδίας</span>) <span class=\"greek\">καρπὸν</span> <span class=\"greek\">πλείονα</span> mais fruto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:2</a>, 8 P66; Hs 5, 2, 4. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄχλου</span> a maior parte da multidão 8, 1, 16. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πλείονα</span> <span class=\"greek\">χρόνον</span> durante mais tempo (PTebt 6:31 [II a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:20</a>. Seguido de gen. de comparação: <span class=\"greek\">πλείονα</span> <span class=\"greek\">τιμήν</span> mais honra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:3b</a>.—IPol 1:3a. Seguido de <span class=\"greek\">παρά</span> <span class=\"greek\">τινα</span> para comparação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:3a</a>; 11:4; Hs 9, 18, 2. <span class=\"greek\">ὅσῳ</span> <span class=\"greek\">πλείονος</span> <span class=\"greek\">κατηξιώθημεν</span> <span class=\"greek\">γνώσεως</span>, <span class=\"greek\">τοσούτῳ</span> <span class=\"greek\">μᾶλλον</span> 1 Cl 41:4.—<span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">μέρος</span> como ac. adv., na maior parte Hv 3, 6, 4a.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Como substantivo <span class=\"greek\">πλεῖον</span>, <span class=\"greek\">πλέον</span> mais <span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖον</span> a soma maior (cf. Diod S 1, 82, 2=a maior parte; Ps 89:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:43</a>. <span class=\"greek\">πλεῖον</span> <span class=\"greek\">λαμβάνειν</span> receber uma soma maior <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:10</a>. Com gen. partitivo <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">προκόψουσιν</span> <span class=\"greek\">ἀσεβείας</span> chegarão a uma medida cada vez maior de impiedade=envolver-se-ão cada vez mais profundamente na impiedade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:16</a>. Com gen. de comparação <span class=\"greek\">πλεῖον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τροφῆς</span> algo maior (mais importante) que o alimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:23</a>. <span class=\"greek\">πλεῖον</span> <span class=\"greek\">Ἰωνᾶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:41</a>; cf. v. 42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:31</a>, 32. <span class=\"greek\">ἡ</span> <span class=\"greek\">χήρα</span> <span class=\"greek\">πλεῖον</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἔβαλεν</span> a viúva depositou mais que todos os demais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:3</a>. <span class=\"greek\">μηδὲν</span> <span class=\"greek\">πλέον</span> nada mais (Jos., Bell. 1, 43; cf. Just., D. 2, 3 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">πλέον</span>); as palavras subsequentes que, exceto, são expressas por <span class=\"greek\">παρά</span> e o ac. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:13</a> ou por <span class=\"greek\">πλήν</span> com gen. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:28</a>, com <span class=\"greek\">εἰ</span> <span class=\"greek\">μή</span> Hs 1:6.—O ac. é usado como adv., mais, em maior medida, em maior grau (Herm. Wr. 13, 21 Nock segundo os manuscritos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:42</a>; IRo 1:1; IEph 6:2; com gen. de comparação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:20</a> (<span class=\"greek\">περισσεύω</span> 1a<span class=\"greek\">β</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:15</a>; IPol 5:2 (v. Ad’Alès, RSR 25, ’35, 489–92). <span class=\"greek\">τριετίαν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πλεῖον</span> durante três anos ou até mais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:18</a> D (cf. TestAbr B 7 p. 111, 27 [Stone p. 70, 27]).—<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πλεῖον</span> mais adiante (de lugar) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:17</a> (TestGad 7:2; Ath. 12 [<span class=\"greek\">ἐπί</span> 4b<span class=\"greek\">β</span>]); (de tempo) longamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:9</a> (<span class=\"greek\">ἐπί</span> 18c<span class=\"greek\">β</span>) ou por mais tempo, por tempo demasiado 24:4; 1 Cl 55:1 (<span class=\"greek\">ἐπί</span> 18c<span class=\"greek\">β</span>); mais, ainda mais (<span class=\"greek\">ἐπί</span> 13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:9</a>; 1 Cl 18:3 (Ps 50:4). Reforçado <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλέον</span> muito mais, com muito maior razão (4 Macc 1:8; cf. X., An. 7, 5, 15; BGU 180, 12f [172 d.C.] <span class=\"greek\">πολλῷ</span> <span class=\"greek\">πλεῖον</span>; Ar. 11, 7 <span class=\"greek\">πολλῷ</span> <span class=\"greek\">πλεῖον</span>) Dg 2:7; 4:5.—Também com indicações de número (v. 1b<span class=\"greek\">α</span>) <span class=\"greek\">πλεῖον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἄρτοι</span> <span class=\"greek\">πέντε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:13</a> (as palavras <span class=\"greek\">πλ</span>. <span class=\"greek\">ἤ</span> fora da construção, como X., An. 1, 2, 11). Em <span class=\"greek\">πλείω</span> <span class=\"greek\">δώδεκα</span> <span class=\"greek\">λεγιῶνας</span> <span class=\"greek\">ἀγγέλων</span> mais de doze legiões de anjos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:53</a>, o texto é incerto (B-D-F §185, 4; v. Rob. 666).—O adv. pode também ser expresso por <span class=\"greek\">πλειόνως</span> (Aeneas Tact. 237; Jos., Ant. 17, 2; Leontios 24, p. 52, 10) mais <span class=\"greek\">ὅσον</span> … <span class=\"greek\">πλειόνως</span> quanto mais … tanto mais IEph 6:1.</p><p class=\"entry-text\">ⓒ Superl. <span class=\"greek\">πλεῖστος</span>, <span class=\"greek\">ον</span></p><p class=\"entry-text\"><span class=\"greek\">α</span>. Adj.</p><p class=\"entry-text\">א . Superlativo propriamente dito <span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖστον</span> <span class=\"greek\">μέρος</span> a maior parte, com gen. partitivo Hs 8, 2, 9; 9, 7, 4. Como ac. adv., na maior parte 8, 5, 6; 8, 10, 1 (v. <span class=\"greek\">μέρος</span> 1d).</p><p class=\"entry-text\">ב . Elativo (v. Mayser II/1, 1926, 53), muito grande, numerosíssimo (<span class=\"greek\">ὁ</span>) <span class=\"greek\">πλεῖστος</span> <span class=\"greek\">ὄχλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:8</a> (<span class=\"greek\">ὁ</span> <span class=\"greek\">πλεῖστος</span> <span class=\"greek\">ὄχλος</span> poderia também ser a maior parte da multidão, como Thu. 7, 78, 2; Pla., Rep. 3, 397d); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:1</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Substantivado <span class=\"greek\">οἱ</span> <span class=\"greek\">πλεῖστοι</span> a maioria, a maior parte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:32</a> D (Just., D. 1, 4; cf. D. 48, 4 <span class=\"greek\">πλεῖστοι</span>).</p><p class=\"entry-text\">③ Relativo a ocupar posição elevada numa escala de extensão.</p><p class=\"entry-text\">ⓐ Grau positivo <span class=\"greek\">πολύς</span>, <span class=\"greek\">πολλή</span>, <span class=\"greek\">πολύ</span></p><p class=\"entry-text\"><span class=\"greek\">α</span>. Como simples adj., para denotar grau, muito, grande, forte, severo, árduo, profundo (Diod S 13, 7, 4 <span class=\"greek\">πολὺς</span> <span class=\"greek\">φόβος</span>; escol. sobre Apollon. Rhod. 4, 57; 58 p. 265, 3 <span class=\"greek\">πολλὴ</span> <span class=\"greek\">δικαιοσύνη</span>; Eccl 5:16 <span class=\"greek\">θυμὸς</span> <span class=\"greek\">π</span>.; Sir 15:18 <span class=\"greek\">σοφία</span>; TestAbr A 20 p. 103, 4 [Stone p. 54] <span class=\"greek\">ἀθυμία</span>; Just., D. 3, 1 <span class=\"greek\">ἠρεμία</span>) <span class=\"greek\">ἀγάπη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:4</a>. <span class=\"greek\">ἀγών</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:2</a>. <span class=\"greek\">ἄθλησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:32</a>. <span class=\"greek\">ἁπλότης</span> Hv 3, 9, 1. <span class=\"greek\">ἀσιτία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:21</a>. <span class=\"greek\">βία</span> 24:6 [7] v.l. <span class=\"greek\">γογγυσμός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:12</a>. <span class=\"greek\">διακονία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:40</a>. <span class=\"greek\">δοκιμή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:2</a>. <span class=\"greek\">δόξα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:30</a>; Hv 1, 3, 4; 2, 2, 6. <span class=\"greek\">δύναμις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:26</a>. <span class=\"greek\">ἐγκράτεια</span> rigoroso domínio de si Hv 2, 3, 2. <span class=\"greek\">εἰρήνη</span> paz completa ou imperturbada (Diod S 3, 64, 7; 11, 38, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:2</a>. <span class=\"greek\">ἔλεος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:3</a>. <span class=\"greek\">ἐπιθυμία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:17</a>. <span class=\"greek\">ζημία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:10</a>. <span class=\"greek\">ζήτησις</span> 15:7. <span class=\"greek\">θλῖψις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:4a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:6</a>. <span class=\"greek\">καύχησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:4b</a> (pred.). <span class=\"greek\">μακροθυμία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:22</a>. <span class=\"greek\">ὀδυρμός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:18</a>. <span class=\"greek\">παράκλησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:4</a>. <span class=\"greek\">παρρησία</span> (Wsd 5:1) 3:12; 7:4a (pred.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:13</a>; Phlm 8. <span class=\"greek\">πεποίθησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:22c</a>. <span class=\"greek\">πλάνη</span> 2 Cl 1:7. <span class=\"greek\">πληροφορία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:5</a>. <span class=\"greek\">πόνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:13</a>. <span class=\"greek\">σιγή</span> um grande silêncio ou silêncio geral (X., Cyr. 7, 1, 25; Arrian, Anab. 5, 28, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:40</a>. <span class=\"greek\">στάσις</span> 23:10. <span class=\"greek\">τρόμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:3</a>. <span class=\"greek\">φαντασία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:23</a>. <span class=\"greek\">χαρά</span> 8:8; Phlm 7. <span class=\"greek\">ὥρα</span> <span class=\"greek\">πολλή</span> hora avançada (Polyb. 5, 8, 3; Dionys. Hal. 2, 54; Jos., Ant. 8, 118) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:35ab</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Substantivado <span class=\"greek\">πολλά</span> no ac. usado como adv., grandemente, fervorosamente, rigorosamente, em voz alta, frequentemente etc. (X., Cyr. 1, 5, 14; Diod S 13, 41, 5; Lucian, Dial. Deor. 19, 2; Aelian, VH 1, 23; 4 Km 10:18; Is 23:16; TestSol 1:1; GrBar; ApcMos; Jos., Ant. 14, 348) <span class=\"greek\">ἀλαλάζειν</span> <span class=\"greek\">πολλά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:38</a> (v. <span class=\"greek\">ἀλαλάζω</span>). <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἁμαρτάνειν</span> Hs 4:5c (ApcMos 32). <span class=\"greek\">π</span>. <span class=\"greek\">ἀνακρίνειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:18</a> v.l. <span class=\"greek\">π</span>. <span class=\"greek\">ἀπορεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:20</a> (Field, Notes 29). <span class=\"greek\">π</span>. <span class=\"greek\">ἀσπάζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:19</a> (v. <span class=\"greek\">ἀσπάζομαι</span> 1a). <span class=\"greek\">δεηθῆναι</span> <span class=\"greek\">π</span>. (GrBar 4:14; Jos., Vi. 173; 343) Hs 5, 4, 1. <span class=\"greek\">διαστέλλεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:43</a> (v. <span class=\"greek\">διαστέλλω</span>). <span class=\"greek\">π</span>. <span class=\"greek\">ἐπιτιμᾶν</span> 3:12. <span class=\"greek\">π</span>. <span class=\"greek\">ἐρωτᾶν</span> orar fervorosamente Hv 2, 2, 1. <span class=\"greek\">κατηγορεῖν</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:3</a> (v. <span class=\"greek\">κατηγορέω</span> 1a). <span class=\"greek\">κηρύσσειν</span> <span class=\"greek\">π</span>. falar livremente 1:45. <span class=\"greek\">κλαίειν</span> amargamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:24</a> D (ApcMos 39). <span class=\"greek\">κοπιᾶν</span> (ApcMos 24; CIG IV 9552, 5 … <span class=\"greek\">μοι</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἐκοπίασεν</span>, cf. Dssm., LO 266, 5 [LAE 317]) trabalhar arduamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:6</a>, 12; 2 Cl 7:1b. <span class=\"greek\">νηστεύειν</span> <span class=\"greek\">π</span>. jejuar frequentemente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:14a</a>. <span class=\"greek\">ὀμνύναι</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:23</a>. <span class=\"greek\">παρακαλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:10</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:1</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:12</a>. <span class=\"greek\">π</span>. <span class=\"greek\">πταίειν</span> cometer muitos erros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:2</a>. <span class=\"greek\">π</span>. <span class=\"greek\">σπαράσσειν</span> convulsionar violentamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:26a</a>.—Com art. <span class=\"greek\">ἐνεκοπτόμην</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πολλά</span> fui impedido essas muitas vezes (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:13</a> <span class=\"greek\">πολλάκις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:22</a> (v.l. <span class=\"greek\">πολλάκις</span> também aqui).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Substantivado <span class=\"greek\">πολύ</span> no ac. usado como adv., grandemente, muitíssimo, intensamente (Da 6:15, 24 Theod.) <span class=\"greek\">ἀγαπᾶν</span> <span class=\"greek\">πολύ</span> mostrar muita afeição, amar muito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:47b</a>. <span class=\"greek\">κλαίειν</span> <span class=\"greek\">π</span>. chorar em voz alta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:4</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:27</a>.</p><p class=\"entry-text\">ⓑ Superlativo, o ac. neut. <span class=\"greek\">πλεῖστον</span>, <span class=\"greek\">α</span> como adv. (sing. Hom. et al.; pl. Pind. et al.)</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Pl. <span class=\"greek\">πλεῖστα</span> na fórmula de saudação no início de uma carta <span class=\"greek\">πλεῖστα</span> <span class=\"greek\">χαίρειν</span> (POxy 742; 744; 1061 [todos os três I a.C.]; PTebt 314, 2 [II d.C.] e muito frequentemente em papiros.—Griech. pap ed. Ltzm.: Kl. Texte 142, 1910, p. 4, 5, 6, 7 e outros; Preis. II s.v. <span class=\"greek\">πλεῖστος</span>) cordialíssima(s) saudação(ões) IEph ins; IMg ins; ITr ins; IRo ins; ISm ins; IPol ins.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Sing. <span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖστον</span> no máximo (Aristoph., Vesp. 260; Diod S 14, 71, 3 <span class=\"greek\">πεμπταῖοι</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ἑκταῖοι</span>; POxy 58, 17; PGiss 65:9) <span class=\"greek\">κατὰ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τρεῖς</span> (palavra por palavra como <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 32, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:27</a>.—B. 922f. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυσπλαγχνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυσπλαγχνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">πολύσπλαγχνος</span>), grau muito elevado de afeição e compaixão por alguém, simpatia, compaixão, misericórdia (Just., D. 55, 3) como atributo divino Hv 1, 3, 2; 2, 2, 8; 4, 2, 3; m 9:2.—DELG s.v. <span class=\"greek\">σπλήν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύσπλαγχνος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολύσπλαγχνος</span>, <span class=\"greek\">ον</span> relativo a um grau muito elevado de afeição e compaixão por alguém, compreensivo, compassivo, misericordioso (cf. artigo anterior; Clem. Alex., Quis Div. Salv. 39, 6; AcThom 119 [Aa II/2 p. 229, 11f]) acerca de Deus (cf. <span class=\"greek\">πολυέλεος</span> Ps 102:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:11</a>; Hm 4, 3, 5; Hs 5, 7, 4.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυτέλεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυτέλεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τέλος</span>; Hdt. et al.; Diod S 5, 42, 6; inscrições [OGI 383, 69: I a.C.]; EpArist 80; Philo; Jos., Ant. 11, 200, C. Ap. 2, 234), despesa na manutenção de um estilo de vida que excede em muito o que se considera normal, extravagância, luxo, riqueza. Em Hs 1:10f. <span class=\"greek\">π</span>. é empregado primeiro lit. <span class=\"greek\">τὴν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">πολυτέλειαν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πράσσετε</span> portanto, não pratiqueis a extravagância das nações (incrédulos) e depois metaf. <span class=\"greek\">τὴν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">πολυτέλειαν</span> <span class=\"greek\">πράσσετε</span> mas praticai vossa própria espécie de extravagância (conforme descrito nos vv. 8f). <span class=\"greek\">π</span>. <span class=\"greek\">ἐδεσμάτων</span> <span class=\"greek\">πολλῶν</span> luxo de muitos (tipos de) alimentos Hm 6, 2, 5. <span class=\"greek\">π</span>. <span class=\"greek\">πλούτου</span> extravagância da riqueza (isto é, tal como a riqueza proporciona) m 8:3; 12, 2, 1.—DELG s.v. <span class=\"greek\">τέλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυτελής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυτελής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">τέλος</span>; Hdt. et al.; inscrições, papiros, LXX; En; TestSol 5:1 D; TestJob; TestJud 26:3; JosAs), relativo a ser de grande valor ou merecimento, ordinariamente de grau relativamente elevado em uma escala monetária, (muito) caro, dispendioso (assim Thu.+; inscrições, papiros, LXX, Philo; Jos., C. Ap. 2, 191), acerca de unguento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:3</a>. De vestuário (X., An. 1, 5, 8; Diod S 4, 53, 3; 17, 35, 2; Polyaenus 6, 1, 4; Philo, Sacr. Abel. 21; Jos., Bell. 1, 605) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:9</a>. De pedras (Diod S 1, 33, 3; 2, 16, 4; OGI 90, 34; 132, 8 [v. nota 7]; SEG VIII 467, 16 [217 a.C.]; PGM 5, 239. Assim sobretudo LXX; En 18:6; EpArist 60 e outros) <span class=\"greek\">λίθος</span> <span class=\"greek\">π</span>. B 6:2 (Is 28:16); pl. MPol 18:2. <span class=\"greek\">παρατάξεις</span> <span class=\"greek\">π</span>. instalações dispendiosas (v. <span class=\"greek\">παράταξις</span> 2) Hs 1:1.—Metaf., acerca do adorno interior <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πολυτελές</span> (isto é, Deus lhe atribui alto valor) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:4</a>.—DELG s.v. <span class=\"greek\">τέλος</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυτελῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυτελῶς</span> adv. de <span class=\"greek\">πολυτελής</span> (desde Eupolis Com. 335 K. [V a.C.]; Lysias 7, 31; Diod S 5, 41, 2; OGI 524, 7; Philo, Mos. 2, 95; Jos., Ant. 8, 95; 18, 92), relativo a despesa de grau muito elevado em uma escala, abundantemente, prodigamente, metaf. (cf. o emprego metaf. s.v. <span class=\"greek\">πολυτέλεια</span> e <span class=\"greek\">πολυτελής</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐργάζεσθαι</span> praticar o bem prodigamente Hm 4, 2, 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολύτιμος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολύτιμος</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">τιμάω</span>; Cornutus 16 p. 21, 16; Plut., Pomp. 621 [5, 2]; Alciphron 3, 10, 4; Herodian 1, 17, 3; POxy 1121, 20 [II d.C.]; PHerm 9, 7; TestSol 22:16 P; TestAbr; JosAs 7:4; 3:9 cód. A; Jos., Ant. 7, 161; Tat. 30, 1 [comp.]), relativo a ocupar posição muito elevada em uma escala monetária, muito precioso, valioso, acerca de uma pérola <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:46</a>. De um unguento 26:7 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a>. Comp. <span class=\"greek\">τὸ</span> <span class=\"greek\">δοκίμιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">πολυτιμότερον</span> <span class=\"greek\">χρυσίου</span> a autenticidade (<span class=\"greek\">δοκίμιον</span> 2) de (vossa) fé, que é mais preciosa que o ouro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:7</a>.—DELG s.v. <span class=\"greek\">τιμή</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πολυτρόπως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πολυτρόπως</span> adv. (<span class=\"greek\">πολύτροπος</span> ‘variado, multiforme’; Philo, Aet. M. 129; Geopon. 9, 11, 4; 4 Macc 3:21 v.l.) de <span class=\"greek\">πολύτροπος</span> (Hom.+; PFlor 33, 15; Job 5:13 v.l.; 4 Macc; ApcMos 24; Philo, Vi. Mos. 1, 117, Dec. 83; Jos., Ant. 10, 142), relativo a uma variedade de modos de expressar algo, de muitas maneiras (com <span class=\"greek\">πολυμερῶς</span>, v. esse lema) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:1</a>.—DELG s.v. <span class=\"greek\">τρέπω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πόμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πόμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">πίνω</span>; assim Pind., Hdt. e escritores posteriores, também Kaibel 244, 10; LXX; TestReub 2:7; Philo; Just., A I, 66, 2 em lugar do ático <span class=\"greek\">πῶμα</span>. Kühner-Bl. II 286), algo que satisfaz a sede, bebida</p><p class=\"entry-text\">ⓐ Pl., acerca de bebidas usuais (com <span class=\"greek\">βρώματα</span>; v. <span class=\"greek\">βρῶμα</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:10</a>; GJs 1:4.</p><p class=\"entry-text\">ⓑ Em linguagem figurada (Ael. Aristid. 28, 114 K.=49 p. 528 D.: <span class=\"greek\">π</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">Ἀπόλλωνος</span> <span class=\"greek\">πηγῶν</span>; Philo, Somn. 2, 248 <span class=\"greek\">θεῖον</span> <span class=\"greek\">π</span>.; SibOr 5, 240) <span class=\"greek\">ἓν</span> <span class=\"greek\">πόμα</span> <span class=\"greek\">ἐποτίσθημεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:13</a> v.l., provavelmente em referência à Eucaristia. O antecedente tipológico da Eucaristia no AT é visto (ao lado do maná como o <span class=\"greek\">πνευματικὸν</span> <span class=\"greek\">βρῶμα</span>) como <span class=\"greek\">τὸ</span> <span class=\"greek\">πνευματικὸν</span> <span class=\"greek\">πόμα</span> a bebida espiritual (da rocha espiritual que os seguia) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:4</a>. Inácio descreve as alegrias da comunhão com Cristo que acompanham o martírio por meio de expressões tomadas da liturgia da Eucaristia, entre elas <span class=\"greek\">πόμα</span> IRo 7:3 (Hdb. ad loc.).—DELG s.v. <span class=\"greek\">πίνω</span> B. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0293-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πονέω</span> (<span class=\"greek\">πόνος</span>) fut. <span class=\"greek\">πονέσω</span> LXX; 1º aor. <span class=\"greek\">ἐπονεσα</span> LXX, inf. <span class=\"greek\">πονέσαι</span> (Just., D. 90, 2) e <span class=\"greek\">πονῆσαι</span> (TestSol 6:13 D); perf. part. pl. gen. <span class=\"greek\">πεπονηκότων</span> (Ath., R. 17 p. 69, 11). Pass.: aor. part. neut. pl. <span class=\"greek\">πονηθέντα</span> (Just., A II, 10, 2) (Pind. et al. [a voz méd. como depoente já em Hom.]; inscrições, papiros, LXX; PsSol 2:14; TestSol; JosAs 25:3; Jos., Ant. 12, 240; 15, 33; Just.; Ath., R. 17 p. 69, 11), dedicar-se a qualquer espécie de trabalho árduo, labutar, sofrer dificuldades <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> acerca de alguém ou em seu favor <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">καταπονουμένῳ</span> (v. <span class=\"greek\">καταπονέω</span>) B 20:2; D 5:2. <span class=\"greek\">πονεῖ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">υἱοῖς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> Ox 1 verso, 17f (GTh 28) (acerca da <span class=\"greek\">ψυχή</span> como Philo, Somn. 1, 255). Uma restauração incerta <span class=\"greek\">εἰ</span> <span class=\"greek\">πο̣ν̣ε̣</span>[<span class=\"greek\">ῖ</span>]<span class=\"greek\">ς</span> AcPl Ha 7, 30.—DELG s.v. <span class=\"greek\">πένομαι</span>.</p></section></article>"};
